// Generated by `npm run generate -w packages/figma`: don't edit (from overrides.json, properties.json and library.json).
import figma from "figma";

const instance = figma.selectedInstance;

const attr = (name, value) => {
  if (value === undefined || value === false) return "";
  if (value === true) return ` ${name}`;
  if (typeof value === "number") return ` ${name}={${value}}`;
  return value.startsWith("{") ? ` ${name}=${value}` : ` ${name}="${value}"`;
};
const codeOf = (node) =>
  node && node.type === "INSTANCE" ? node.executeTemplate().example : undefined;

const children = instance.getEnum("Content", {
  initials: true,
  icon: false,
  image: false,
})
  ? instance.getString("Initials")
  : undefined;
const icon = instance.getEnum("Content", {
  initials: false,
  icon: true,
  image: false,
})
  ? codeOf(instance.getInstanceSwap("Icon"))
  : undefined;
const size = instance.getEnum("Size", {
  xs: "xs",
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
});
const variant = instance.getEnum("Shape", {
  circular: "circular",
  square: "square",
});

export default {
  id: "Avatar",
  example: figma.code`<HvAvatar${attr("size", size)}${attr("variant", variant)}>${children ?? ""}${icon ?? ""}</HvAvatar>`,
  imports: ['import { HvAvatar } from "@pentaho/uikit-react-core";'],
  metadata: { nestable: true },
};
